// spec: .qa/e2e/specs/reminders.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('Напоминания', () => {
  test('RM-02 «תזכורות במערכת» выключен → «התזכורות כבויות — אפשר להפעיל בפרופיל»; «ניהול תזכורות» ведёт к тумблеру #6a86f7fa @data @mobile', async ({ page }) => {
    const reminderSwitch = () => page.getByRole('switch', { name: /^תזכורות במערכת/ });
    try {
      // 1. Открыть `/profile` → switch «תזכורות במערכת» → выключить.
      await page.goto('/profile');
      await expect(reminderSwitch()).toHaveAttribute('aria-checked', 'true'); // исходно включён
      await reminderSwitch().click();
      await expect(page.getByRole('alert').filter({ hasText: 'תזכורות במערכת: השינוי נשמר.' })).toBeVisible();
      await expect(reminderSwitch()).toHaveAttribute('aria-checked', 'false');

      // 2. Открыть `/home` → «תזכורות מהירות» → «ניהול תזכורות».
      await page.goto('/home');
      const title = page.getByText('תזכורות מהירות', { exact: true });
      await expect(title).toBeVisible({ timeout: 20_000 });
      const block = title.locator('xpath=../..');
      await expect(block.getByText('התזכורות כבויות — אפשר להפעיל בפרופיל')).toBeVisible();
      await expect(block.getByText('אין כרגע תזכורות פעילות.')).toHaveCount(0);

      await block.getByRole('button', { name: 'ניהול התזכורות במסך הפרופיל' }).click();
      await expect(page).toHaveURL(/\/profile\?focus=reminders$/);
      await expect(reminderSwitch()).toBeInViewport();
    } finally {
      // 3. Уборка: включить switch обратно; reload `/profile` и `/home`.
      await page.goto('/profile');
      await expect(page.getByRole('switch', { name: /תזכורות במערכת/ })).toBeVisible();
      if ((await reminderSwitch().getAttribute('aria-checked')) !== 'true') {
        await reminderSwitch().click();
        await expect(page.getByRole('alert').filter({ hasText: 'תזכורות במערכת: השינוי נשמר.' })).toBeVisible();
      }
      await page.reload();
      await expect(reminderSwitch()).toHaveAttribute('aria-checked', 'true');
      await page.goto('/home');
      await expect(page.getByText('התזכורות כבויות — אפשר להפעיל בפרופיל')).toHaveCount(0, { timeout: 20_000 });
      await expect(page.getByText('תזכורות מהירות', { exact: true })).toBeVisible();
    }
  });
});
